import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int n = 0;
            while (b >= '0' && b <= '9') {
                n = n * 10 + (b - '0');
                b = readByte();
            }
            return n;
        }
    }

    private int N, M;
    private int[] head;
    private int[] deg;
    private int[] to;
    private int[] memoS;
    private int[] memoDP;

    public static void main(String[] args) throws Exception {
        Thread t = new Thread(null, () -> {
            try {
                new Main().solve();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, "Solver", 1 << 26);
        t.start();
        t.join();
    }

    private void solve() {
        FastScanner sc = new FastScanner();
        N = sc.nextInt();
        if (N == -1) return;
        M = sc.nextInt();

        int[] uEdges = new int[M];
        int[] vEdges = new int[M];
        deg = new int[N + 1];

        for (int i = 0; i < M; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            uEdges[i] = u;
            vEdges[i] = v;
            deg[u]++;
            deg[v]++;
        }

        head = new int[N + 2];
        for (int i = 1; i <= N; i++) {
            head[i + 1] = head[i] + deg[i];
        }

        to = new int[2 * M];
        int[] cur = new int[N + 1];
        System.arraycopy(head, 1, cur, 1, N);

        for (int i = 0; i < M; i++) {
            int u = uEdges[i];
            int v = vEdges[i];
            to[cur[u]++] = v;
            to[cur[v]++] = u;
        }

        for (int i = 1; i <= N; i++) {
            if (deg[i] > 1) {
                Arrays.sort(to, head[i], head[i] + deg[i]);
            }
        }

        memoS = new int[2 * M];
        memoDP = new int[2 * M];

        PrintWriter out = new PrintWriter(System.out);
        for (int i = 1; i <= N; i++) {
            int ans = 1 + getS(i, 0);
            out.print(ans);
            if (i < N) {
                out.print(" ");
            }
        }
        out.println();
        out.flush();
    }

    private int getS(int v, int i) {
        if (i >= deg[v]) return 0;
        int idx = head[v] + i;
        if (memoS[idx] != 0) return memoS[idx];

        int dpVal = getDP(v, i);
        int nextS = getS(v, i + 1);
        int res = (dpVal > nextS) ? dpVal : nextS;

        return memoS[idx] = res;
    }

    private int getDP(int v, int i) {
        int edgeIdx = head[v] + i;
        if (memoDP[edgeIdx] != 0) return memoDP[edgeIdx];

        int w = to[edgeIdx];
        int nextIdx = binarySearch(w, v);
        int res = 1 + getS(w, nextIdx);

        return memoDP[edgeIdx] = res;
    }

    private int binarySearch(int w, int val) {
        int low = 0;
        int high = deg[w];
        int h = head[w];
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (to[h + mid] > val) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
