const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = readInt();
    if (n === null) return;
    const m = readInt();

    const edge_u = new Int32Array(m);
    const edge_v = new Int32Array(m);
    const deg = new Int32Array(n + 1);

    for (let i = 0; i < m; i++) {
        const u = readInt();
        const v = readInt();
        edge_u[i] = u;
        edge_v[i] = v;
        deg[u]++;
        deg[v]++;
    }

    const head_adj = new Int32Array(n + 2);
    for (let i = 1; i <= n; i++) {
        head_adj[i + 1] = head_adj[i] + deg[i];
    }
    const cur_adj = new Int32Array(head_adj);
    const adj = new Int32Array(2 * m);

    for (let i = 0; i < m; i++) {
        const u = edge_u[i];
        const v = edge_v[i];
        adj[cur_adj[u]++] = v;
        adj[cur_adj[v]++] = u;
    }

    for (let i = 1; i <= n; i++) {
        const start = head_adj[i];
        const end = head_adj[i + 1];
        if (end - start > 1) {
            adj.subarray(start, end).sort();
        }
    }

    const bit = new Int32Array(2 * m + 2);
    bit.fill(1);

    function queryBIT(v, u) {
        const start = head_adj[v];
        const count = deg[v];
        let l = 0, r = count - 1;
        let idx = -1;
        while (l <= r) {
            const mid = (l + r) >> 1;
            if (adj[start + mid] > u) {
                idx = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        if (idx === -1) return 1;

        const k = idx + 1;
        let maxVal = 1;
        const base = head_adj[v];
        for (let p = k; p <= count; p += p & -p) {
            const val = bit[base + p];
            if (val > maxVal) maxVal = val;
        }
        return maxVal;
    }

    function updateBIT(v, w, val) {
        const start = head_adj[v];
        const count = deg[v];
        let l = 0, r = count - 1;
        let idx = -1;
        while (l <= r) {
            const mid = (l + r) >> 1;
            const midVal = adj[start + mid];
            if (midVal === w) {
                idx = mid;
                break;
            } else if (midVal < w) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }

        const k = idx + 1;
        const base = head_adj[v];
        for (let p = k; p > 0; p -= p & -p) {
            if (val > bit[base + p]) {
                bit[base + p] = val;
            }
        }
    }

    const maxSum = 2 * n;
    const countSum = new Int32Array(maxSum + 1);
    for (let i = 0; i < m; i++) {
        countSum[edge_u[i] + edge_v[i]]++;
    }

    const sumHead = new Int32Array(maxSum + 2);
    for (let s = maxSum; s >= 1; s--) {
        sumHead[s] = sumHead[s + 1] + countSum[s];
    }

    const curSum = new Int32Array(sumHead);
    const sortedEdges = new Int32Array(m);
    for (let i = 0; i < m; i++) {
        const s = edge_u[i] + edge_v[i];
        sortedEdges[curSum[s]++] = i;
    }

    const ans = new Int32Array(n + 1);
    ans.fill(1);

    for (let i = 0; i < m; i++) {
        const e = sortedEdges[i];
        const u = edge_u[e];
        const v = edge_v[e];

        const val_uv = 1 + queryBIT(v, u);
        const val_vu = 1 + queryBIT(u, v);

        if (val_uv > ans[u]) ans[u] = val_uv;
        if (val_vu > ans[v]) ans[v] = val_vu;

        updateBIT(u, v, val_uv);
        updateBIT(v, u, val_vu);
    }

